seeds.find(m=>m.id==='bunny').video='assets/big-buck-bunny.mp4';
seeds.find(m=>m.id==='bunny').poster='assets/big-buck-bunny.jpg';
seeds.find(m=>m.id==='bunny').credit+=' · 本站版本压缩画质，保留完整内容与片尾署名';
seeds.find(m=>m.id==='bunny').backdrop=photo('photo-1441974231531-c6227db76b6e',2200);
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
let imported=read('mujian-imports',[]);if(!Array.isArray(imported))imported=[];
let movies=[...seeds,...imported.filter(m=>validMovie(m)&&!seeds.some(s=>s.id===m.id))];
let saved=read('mujian-saved',[]);if(!Array.isArray(saved))saved=[];
let history=read('mujian-history',{});if(!history||typeof history!=='object'||Array.isArray(history))history={};
let view='home',genre='全部',heroIndex=1,currentFilm=null,lastHistoryWrite=0,toastTimer,loadTimer;
const featured=['sintel','bunny','tears'];
function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{toast('浏览器存储不可用，当前更改无法在刷新后保留');return false}}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function safeURL(s){try{if(typeof s!=='string'||!s.trim())return '';const u=new URL(s,location.href);return (u.protocol==='https:'||(u.protocol==='http:'&&u.origin===location.origin))&&!u.username&&!u.password?u.href:''}catch{return ''}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2800)}
function matchesGenre(m){return genre==='全部'||m.genre===genre||(m.tags||[]).includes(genre)}
function render(){
 const q=$('#search').value.trim().toLowerCase(),year=$('#year').value;
 let list=movies.filter(m=>(view!=='open'||m.video)&&(view!=='saved'||saved.includes(m.id))&&matchesGenre(m)&&(!q||[m.title,m.original,m.director].join(' ').toLowerCase().includes(q))&&(year==='all'||(year==='older'?m.year<2000:Math.floor(m.year/10)*10===Number(year))));
 if($('#sort').value==='new')list.sort((a,b)=>b.year-a.year);if($('#sort').value==='title')list.sort((a,b)=>a.title.localeCompare(b.title,'zh'));
 $('#hero').hidden=view!=='home'||!!q;$('#editorial').hidden=view!=='home'||!!q;
 $('#page-title').textContent=q?'寻找心里的那部电影':({home:'今晚，看点什么？',library:'你的电影宇宙',open:'自由开场，好戏上映',saved:'留给下次的好故事'}[view]);
 $('#results-title').innerHTML=(q?'搜索结果':view==='saved'?'我的收藏':view==='open'?'可直接播放的开放电影':'值得一看的好故事')+' <span>THE COLLECTION</span>';
 $('#count').textContent=`${list.length} 部影片`;$('#empty').hidden=!!list.length;
 $('#empty h3').textContent=view==='saved'&&!q?'你的片单，还在等第一个故事':'还没有找到这部电影';
 $('#movies').innerHTML=list.map(m=>`<article class="card"><button class="poster" data-detail="${esc(m.id)}" style="--tint:${/^#[0-9a-f]{3,8}$/i.test(m.tint||'')?m.tint:'#486052'}" aria-label="查看${esc(m.title)}详情">${safeURL(m.poster)?`<img loading="lazy" src="${esc(safeURL(m.poster))}" alt="" referrerpolicy="no-referrer">`:''}<span class="poster-type ${m.video?'open':''}">${m.video?'可在线观看':'精选片单'}</span><span class="poster-title">${esc(m.title)}<small>${esc((m.original||m.title).toUpperCase())}</small></span><span class="play-hover">${m.video?'▶':'＋'}</span></button><button class="save-card ${saved.includes(m.id)?'saved':''}" data-save="${esc(m.id)}" aria-label="${saved.includes(m.id)?'取消收藏':'收藏'}${esc(m.title)}" aria-pressed="${saved.includes(m.id)}">${saved.includes(m.id)?'♥':'♡'}</button><h4>${esc(m.title)}</h4><div class="card-info"><span>${m.year}</span><span>·</span><span>${esc(m.genre)}</span><span class="available">${m.video?'PLAY ↗':'资料'}</span></div></article>`).join('');
 document.querySelectorAll('.poster img').forEach(img=>img.onerror=()=>{img.style.display='none'});
 document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n.dataset.view===view));
 renderHistory();
}
function setView(next){view=next;genre='全部';$('#search').value='';$('#year').value='all';$('#sort').value='recommend';renderGenres();render();window.scrollTo({top:0,behavior:'smooth'})}
function renderGenres(){$('#genres').innerHTML=['全部','科幻','剧情','动画','喜剧','爱情','冒险'].map(g=>`<button class="chip ${g===genre?'active':''}" data-genre="${g}" aria-pressed="${g===genre}">${g}</button>`).join('')}
function toggleSave(id){if(saved.includes(id)){saved=saved.filter(x=>x!==id);toast('已从片单移除')}else{saved.push(id);toast('已加入我的片单')}persist('mujian-saved',saved);render();if($('#details').open)detail(id,false)}
function detail(id,open=true){const m=movies.find(m=>m.id===id);if(!m)return;
 $('#detail-content').innerHTML=`<div class="detail-banner">${safeURL(m.poster)?`<img src="${esc(safeURL(m.poster))}" alt="${esc(m.title)}${seeds.includes(m)&&!m.video?'意境配图':'剧照'}">`:''}</div><div class="detail-body"><p class="detail-original">${esc(m.original||'MUJIAN COLLECTION')}</p><h2>${esc(m.title)}</h2><div class="detail-tags"><span>${m.year}</span><span>${esc(m.genre)}</span><span>${m.duration?esc(m.duration)+' 分钟':''}</span><span>${m.video?'可在线观看':'电影资料'}</span></div><p>导演 / ${esc(m.director||'暂未提供')}</p><p>${esc(m.description||'这部电影的故事，等待你来发现。')}</p><div class="detail-actions">${m.video?`<button class="primary" data-play="${esc(m.id)}">▶ &nbsp; ${history[id]?.time>10?'继续观看':'立即观看'}</button>`:`<a class="primary" href="https://www.themoviedb.org/search?query=${encodeURIComponent(m.original||m.title)}" target="_blank" rel="noopener">探索影片资料 ↗</a>`}<button class="secondary" data-save="${esc(m.id)}">${saved.includes(m.id)?'♥ 已收藏':'＋ 加入片单'}</button></div><p class="credit">${m.video?esc(m.credit||'视频由片库导入者提供，请确保拥有播放授权。'):'当前仅收录影片资料。本站尚无本片播放资源。卡片与详情背景为意境配图，非官方海报。'}${safeURL(m.source)?`<br><a href="${esc(safeURL(m.source))}" target="_blank" rel="noopener">查看作品来源 ↗</a>`:''}${seeds.includes(m)&&m.video?` · <a href="${m.license||'https://creativecommons.org/licenses/by/3.0/'}" target="_blank" rel="noopener">许可协议</a>`:''}</p></div>`;
 if(open)$('#details').showModal();
}
function play(id){const m=movies.find(m=>m.id===id);if(!m||!safeURL(m.video))return;$('#details').close();currentFilm=m;lastHistoryWrite=0;
 const v=$('#video');v.src=safeURL(m.video);v.poster=safeURL(m.poster);$('#playing-title').textContent=m.title+' / '+(m.original||'');$('#video-status').textContent='正在连接视频资源…';
 $('#player-credit').textContent=m.credit||'自有 / 授权视频资源';$('#player-dialog').showModal();v.load();
 clearTimeout(loadTimer);loadTimer=setTimeout(()=>{if(currentFilm?.id===id&&v.readyState<2)$('#video-status').textContent='视频源响应较慢或当前网络不可达。请稍后重试，或选择其他影片。'},15000);
 v.play().catch(()=>{if(!currentFilm||currentFilm.id!==id)return;$('#video-status').textContent=v.error?'视频暂时无法加载，请检查网络或选择其他影片。':'点击播放器中的播放按钮开始观看。'});
}
function saveProgress(){const v=$('#video');if(currentFilm&&Number.isFinite(v.duration)&&v.currentTime>0){history[currentFilm.id]={time:v.currentTime,duration:v.duration,updated:Date.now()};persist('mujian-history',history)}}
function renderHistory(){const entries=Object.entries(history).filter(([id,h])=>movies.some(m=>m.id===id)&&h.time>5&&h.time<h.duration-3).sort((a,b)=>b[1].updated-a[1].updated).slice(0,4);$('#continue-section').hidden=!entries.length||view!=='home';$('#continue-list').innerHTML=entries.map(([id,h])=>{const m=movies.find(m=>m.id===id);return `<div class="history-item">${safeURL(m.poster)?`<img src="${esc(safeURL(m.poster))}" alt="">`:''}<button data-play="${esc(id)}"><strong>${esc(m.title)} &nbsp; ▶</strong><p>已观看 ${Math.floor(h.time/60)}:${String(Math.floor(h.time%60)).padStart(2,'0')} / ${Math.floor(h.duration/60)} 分钟</p><progress value="${h.time}" max="${h.duration}"></progress></button></div>`}).join('')}
$('#video').addEventListener('loadedmetadata',()=>{const h=history[currentFilm?.id];if(h?.time>0&&h.time<$('#video').duration-3)$('#video').currentTime=h.time});
$('#video').addEventListener('playing',()=>{clearTimeout(loadTimer);$('#video-status').textContent='正在播放 · 可使用播放器控制音量、画中画及全屏'});
$('#video').addEventListener('waiting',()=>{$('#video-status').textContent='正在缓冲，请稍候…'});
$('#video').addEventListener('error',()=>{$('#video-status').textContent='视频暂时无法加载。请检查网络，或稍后重新打开影片。外部视频源在部分网络环境可能不可用。'});
$('#video').addEventListener('timeupdate',()=>{if(Date.now()-lastHistoryWrite>5000){saveProgress();lastHistoryWrite=Date.now()}});
$('#video').addEventListener('ended',()=>{saveProgress();$('#video-status').textContent='影片已结束。去发现下一个好故事吧。'});
$('#player-dialog').addEventListener('close',()=>{clearTimeout(loadTimer);saveProgress();$('#video').pause();$('#video').removeAttribute('src');$('#video').load();currentFilm=null;renderHistory()});
$('#restart').onclick=()=>{$('#video').currentTime=0;$('#video').play().catch(()=>{})};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.detail)detail(b.dataset.detail);if(b.dataset.save)toggleSave(b.dataset.save);if(b.dataset.play)play(b.dataset.play);if(b.dataset.view)setView(b.dataset.view);if(b.dataset.genre){genre=b.dataset.genre;renderGenres();render()}if(b.classList.contains('close'))b.closest('dialog').close()});
$('.brand').onclick=e=>{e.preventDefault();setView('home')};
$('#search').addEventListener('input',render);$('#year').onchange=render;$('#sort').onchange=render;
$('#reset').onclick=()=>{genre='全部';$('#search').value='';$('#year').value='all';renderGenres();render()};
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();$('#search').focus()}});
function hero(delta){heroIndex=(heroIndex+delta+featured.length)%featured.length;const m=movies.find(x=>x.id===featured[heroIndex]);$('.hero-image').src=m.backdrop||m.poster;$('.hero-image').alt=m.backdrop?'自然景观意境配图':m.title+'剧照';$('h1').textContent=m.title;$('.english-title').textContent=m.original.toUpperCase().split('').join(' ');$('.hero-kicker').textContent=['一场跨越世界的寻找','森林里的一点小小反击','过去，能否拯救未来'][heroIndex];$('.hero-meta').innerHTML=`<span class="rating">开放电影</span><span>${m.year}</span><span>荷兰</span><span>${esc(m.genre)}</span><span>${m.duration} 分钟</span>`;$('.hero-desc').textContent=m.description.slice(0,75);$('.hero-bottom b').textContent='0'+(heroIndex+1);$('.hero-credit').innerHTML='BLENDER FOUNDATION 开放电影 · CC BY 3.0'+(m.backdrop?'<br><span>背景为意境配图，非电影剧照</span>':'')}
$('#prev-hero').onclick=()=>hero(-1);$('#next-hero').onclick=()=>hero(1);$('#hero-play').onclick=()=>play(featured[heroIndex]);$('#hero-detail').onclick=()=>detail(featured[heroIndex]);$('#explore-open').onclick=()=>setView('open');
$('#clear-history').onclick=()=>{history={};persist('mujian-history',history);renderHistory();toast('已清除观看记录')};
function openImport(){$('#import-status').textContent='';$('#import-file').value='';$('#import-dialog').showModal()}
$('#import-button').onclick=openImport;$('#import-footer').onclick=openImport;
function validMovie(m){return m&&typeof m==='object'&&typeof m.id==='string'&&/^[a-zA-Z0-9_-]{1,80}$/.test(m.id)&&typeof m.title==='string'&&m.title.trim().length>0&&m.title.length<=150&&Number.isInteger(m.year)&&m.year>=1888&&m.year<=2100&&typeof m.genre==='string'&&m.genre.length<=30&&(!m.video||!!safeURL(m.video))&&(!m.poster||!!safeURL(m.poster))&&(!m.source||!!safeURL(m.source))&&(!m.tags||(Array.isArray(m.tags)&&m.tags.length<=20&&m.tags.every(t=>typeof t==='string')))&&['original','director','description','credit'].every(k=>m[k]===undefined||(typeof m[k]==='string'&&m[k].length<=5000))}
$('#import-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>3*1024*1024)throw Error('文件过大，请使用 3MB 以内的 JSON。');const data=JSON.parse(await f.text());if(!Array.isArray(data)||!data.length||data.length>500)throw Error('请提供包含 1–500 个条目的 JSON 数组。');if(!data.every(validMovie))throw Error('条目格式不正确。请检查 id、片名、年代、分类和 HTTPS 资源地址。');const map=new Map(imported.map(m=>[m.id,m]));let count=0;for(const m of data){if(!seeds.some(s=>s.id===m.id)){const clean={};for(const key of ['id','title','year','genre','original','director','description','poster','video','credit','source','tags','duration'])if(m[key]!==undefined)clean[key]=m[key];map.set(m.id,clean);count++}}const next=[...map.values()];if(next.length>2000)throw Error('当前浏览器片库最多保留 2000 条导入影片。');if(!persist('mujian-imports',next))throw Error('保存失败，请检查浏览器存储空间。');imported=next;movies=[...seeds,...imported];render();$('#import-status').textContent=`导入完成，已添加或更新 ${count} 部电影。与内置影片重复的 ID 会跳过。`}catch(err){$('#import-status').textContent=err instanceof SyntaxError?'JSON 格式有误，请检查括号、逗号和引号。':err.message}};
$('#download-template').onclick=()=>{const blob=new Blob([JSON.stringify([{id:'my-film',title:'我的电影',year:2026,genre:'剧情',original:'My Film',director:'导演姓名',description:'影片简介',video:'https://example.com/movie.mp4',credit:'版权所有者 / 授权信息'}],null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='mujian-catalog-template.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
$('#about').onclick=()=>{$('#detail-content').innerHTML='<div class="form-content"><span class="overline">ABOUT MUJIAN</span><h2>把时间交给好电影。</h2><p>幕间是一个中文电影探索项目，当前内置 12 部精选影片资料，其中《大雄兔》完整视频随项目保存，另有 3 部 Blender 开放电影使用外部视频源（部分网络下不可用）。它尚未接入全量电影数据库。</p><p>收藏、播放进度和导入的片库仅保存在当前浏览器。更换设备或清除浏览器数据后不会同步。当前版本没有账号、云端数据库或后台上传服务。</p><p>电影视频 © Blender Foundation 及各作品创作者，具体署名和许可见影片详情。非开放影片仅展示资料，意境配图来自 Unsplash。视频播放依赖第三方资源的网络可用性，影片内置音轨为原版。</p><p>如需扩充片库，请使用页脚的「导入片库」，添加你拥有或已获授权的视频。若要接入在线电影资料数据库及跨设备账号，需要继续配置后端服务。</p><a class="text-button" href="https://studio.blender.org/films/" target="_blank" rel="noopener">了解 Blender 开放电影 ↗</a></div>';$('#details').showModal()};
window.addEventListener('pagehide',saveProgress);renderGenres();hero(0);render();
